from pathlib import Path
from collections import Counter
import json,hashlib,statistics,time
D=Path(__file__).resolve().parent;P=D.parent
load=lambda p:json.loads(p.read_text())
freeze=load(D/'judgment-freeze.json')
for name in ['rubric.json','blind-full.json','judgments-blind.json']:
 assert hashlib.sha256((D/name).read_bytes()).hexdigest()==freeze[name],name
pairs={r['id']:r for r in load(D/'blind-full.json')};key=load(P/'blind-key.json')
judgments=load(D/'judgments-blind.json');raw=[json.loads(l) for l in (P/'results/paired/raw.jsonl').read_text().splitlines()]
counts=Counter();strict=Counter();issues={a:Counter() for a in ['A','B']};out=[]
for j in judgments:
 r=pairs[j['id']];mapping=dict(zip(['X','Y'],key[j['id']]))
 winner=mapping.get(j['winner'],j['winner']);counts[winner]+=1
 strict['boundary_sensitive' if j['boundary_sensitive_verdict'] else winner]+=1
 versions={mapping[s]:{**j[s],'answer':r['versions'][s]} for s in ['X','Y']}
 for arm,v in versions.items():
  for f in ['omissions','unsupported','relation_errors','minor','uncertain']:issues[arm][f]+=bool(v[f])
  issues[arm]['any_clear_issue']+=any(v[f] for f in ['omissions','unsupported','relation_errors'])
 out.append({'id':j['id'],'stock_name':r['stock_name'],'published_at':r['published_at'],'text':r['text'],'verdict':winner,'boundary_sensitive':j['boundary_sensitive_verdict'],'reason':j['reason'],'reference_notes':j['reference_notes'],'frozen_reference':r['reference'],'versions':versions})
cost={}
for arm in ['A','B']:
 rows=[r for r in raw if r['task_id'].endswith('::'+arm)]
 cost[arm]={f:sum(r['response']['usage'].get(f,0) for r in rows) for f in ['prompt_tokens','completion_tokens','total_tokens']}
 cost[arm].update({'requests':len(rows),'median_request_seconds':statistics.median(r['elapsed_seconds'] for r in rows),'sum_overlapping_request_seconds':sum(r['elapsed_seconds'] for r in rows),'format_valid':sum(r['prediction']['status']=='ok' for r in rows)})
summary={'status':'completed_assistant_review','reviewed_posts':80,'reviewed_answers':160,'format_rejects_included_from_raw':6,'verdict_counts':dict(counts),'boundary_sensitive_posts':12,'conservative_counts':dict(strict),'issue_post_counts':{a:dict(v) for a,v in issues.items()},'cost':cost,'B_over_A_completion_token_increase':cost['B']['completion_tokens']/cost['A']['completion_tokens']-1,'B_over_A_total_token_increase':cost['B']['total_tokens']/cost['A']['total_tokens']-1,'B_over_A_median_latency_increase':cost['B']['median_request_seconds']/cost['A']['median_request_seconds']-1,'decision':'B有局部收益，但不足以替换默认版本。原17项任务保留A作基线；下一批K3沿用388条的冻结提示词，不能混用本试验结论。','scope':'助手逐条文本复核，不是真人金标准；X/Y名称在判定冻结前隐藏，但输出风格可暴露组织方式，不是完全盲法。','note':'平局可包含两版都错；帖子存在问题数不是总体错误率。争议项剔除只作敏感性检查，不是重新调参。输出更多不算新增明确含义。','created_epoch':time.time(),'judgment_freeze_sha256':hashlib.sha256((D/'judgment-freeze.json').read_bytes()).hexdigest()}
for name,value in [('summary.json',summary),('review-data.json',{'summary':summary,'rows':out})]:(D/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
(D/'per-post-review.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in out))
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>80条A/B质量比较 · 已完成</title><style>*{box-sizing:border-box}body{margin:0;background:#f2f5f7;color:#162c3d;font:18px/1.7 system-ui}main{max-width:1250px;margin:auto;padding:25px 20px}h1{font-size:30px}h2{font-size:23px}article,.card{background:#fff;border:1px solid #dce4ea;border-radius:12px;padding:20px;margin:18px 0}p,div{overflow-wrap:anywhere}.post{font-size:24px;white-space:pre-wrap}.muted{color:#596d7d;font-size:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.col{background:#f5f8fb;border-radius:8px;padding:15px;min-width:0}.issue{border-left:3px solid #bd663b;padding-left:12px}.obs{border-top:1px solid #dce4ea;margin-top:12px;padding-top:10px}.toolbar{display:flex;gap:10px;flex-wrap:wrap}input,select,button{font:inherit;padding:8px;max-width:100%}a{color:#075f9c}table{width:100%;border-collapse:collapse}td,th{padding:9px;text-align:left;border-bottom:1px solid #dde4ea}.scroll{overflow:auto}summary{cursor:pointer}b{font-weight:650}@media(max-width:760px){.grid{grid-template-columns:1fr}main{padding:18px 12px}.post{font-size:21px}}</style><main><h1>80条A/B质量比较：已逐条复核</h1><div class="card"><b>结论：B 有局部改善，但没有足够证据替换默认版本。</b><p>A 先分类再补额外观察；B 先完整观察再分类。两版使用同一模型和相同原文、类别定义。</p><div class="scroll"><table><thead><tr><th>逐帖比较</th><th>数量（共80帖）</th></tr></thead><tbody><tr><td>B更好</td><td>14</td></tr><tr><td>A更好</td><td>10</td></tr><tr><td>没有明确优劣</td><td>53</td></tr><tr><td>各有得失</td><td>3</td></tr></tbody></table></div><p><b>12条胜负依赖较细的解释边界。</b>把这些争议判断暂不计入，剩余是 B 6胜、A 6胜。平局也可能是两版都错，不能当正确率。</p><p id="cost"></p><p>因此：原17项任务继续保留A作基线；B可作为复核候选，当前不直接扩大替换。下一批K3任务仍沿用388条的冻结口径。</p><p class="muted">阅读了全部80条原文、160个完整回答，包括6次未通过格式校验的原始回答。先按X/Y逐条判断并冻结，再揭开版本。参照是运行前的助手初稿，不是真人金标准；输出风格也可能暴露版本，不能声称完全盲法。没有改动原始回答或训练模型。</p><a href="per-post-review.jsonl">下载逐条复核JSONL</a> · <a href="summary.json">统计及成本JSON</a> · <a href="../exports/review.html">原始X/Y页面</a></div><div class="card"><h2>这次实际暴露了什么</h2><p>B能补回一些信息，例如 O1H061 的“多头抵抗”和“不希望暴涨暴跌”，也能减少一些无依据推断。但B也会漏明确失望（O1H029）、把贪心解释成上涨没有顶部（O1H023），甚至给“节前”补成“春节”（O1H078）。</p><p>两版共同的问题包括：把“出货了”默认成作者已卖出，把反讽抱怨判成恐慌，把“贪心没有止境”理解为价格没有顶部。这些才是本轮留存的具体问题，不能用格式通过率替代。</p><div id="issues" class="scroll"></div></div><div class="toolbar"><input id="q" placeholder="搜索编号、股票、原文"><select id="filter"><option value="all">全部80条</option><option value="B">B更好</option><option value="A">A更好</option><option value="tradeoff">各有得失</option><option value="tie">没有明确优劣</option><option value="boundary">边界敏感</option><option value="errors">至少一版有明确问题</option></select><button id="prev">上一页</button><span id="page"></span><button id="next">下一页</button></div><div id="rows"></div><script>
let rows=[],page=0;const $=s=>document.querySelector(s),names={A:'A更好',B:'B更好',tie:'没有明确优劣',tradeoff:'各有得失'},fields={omissions:'遗漏',unsupported:'无依据补充',relation_errors:'关系/主体/时态误读',minor:'细节问题',uncertain:'保留争议'},labels={emo_fear:'恐惧',emo_regret:'后悔',emo_anger:'愤怒',emo_excitement:'兴奋',emo_fomo:'FOMO',emo_disappointment:'失望',stance_bullish:'看多',stance_bearish:'看空',action_clear:'清仓',topic_price:'价格/走势',topic_funds:'资金/筹码',topic_fundamentals:'经营/基本面',target_other_retail:'其他散户',action_buy_completed:'自述已买入',action_sell_completed:'自述已卖出',action_t_unspecified:'做T',wish_stop_decline:'希望止跌'};const add=(p,t,s,c)=>{const e=document.createElement(t);e.textContent=s;if(c)e.className=c;p.append(e);return e};const hasErrors=r=>Object.values(r.versions).some(v=>['omissions','unsupported','relation_errors'].some(k=>v[k].length));
function render(){const list=rows.filter(r=>[r.id,r.stock_name,r.text,r.reason].join(' ').includes($('#q').value)&&($('#filter').value==='all'||$('#filter').value===r.verdict||$('#filter').value==='boundary'&&r.boundary_sensitive||$('#filter').value==='errors'&&hasErrors(r)));page=Math.min(page,Math.max(0,Math.ceil(list.length/5)-1));$('#page').textContent=`${page+1}/${Math.max(1,Math.ceil(list.length/5))} · ${list.length}帖`;$('#rows').replaceChildren();for(const r of list.slice(page*5,page*5+5)){const a=add($('#rows'),'article','');add(a,'h2',r.id+' · '+r.stock_name+' · '+names[r.verdict]+(r.boundary_sensitive?'（边界敏感）':''));add(a,'p',r.text,'post');add(a,'p',r.reason);for(const n of r.reference_notes)add(a,'p','参照校正说明：'+n,'muted');const grid=add(a,'div','','grid');for(const arm of ['A','B']){const v=r.versions[arm],c=add(grid,'div','','col');add(c,'b',arm+(arm==='A'?' · 先分类':' · 先完整观察'));let issue=false;for(const[k,l]of Object.entries(fields)){if(v[k].length){issue=true;add(c,'p',l+'：'+v[k].join('；'),'issue')}}if(!issue)add(c,'p','本条未记录明确遗漏或误读。','muted');if(v.answer.error)add(c,'p','格式记录：'+v.answer.error+'。本次已阅读其原始回答。','muted');const d=add(c,'details','');add(d,'summary','展开完整判断、原文证据和理由');for(const[k,check]of Object.entries(v.answer.checks||{})){for(const x of check.claims||[]){const e=add(d,'div','','obs');add(e,'b',(labels[k]||k)+' · '+x.state);add(e,'p','「'+x.quote+'」 '+x.reason);add(e,'p',`${x.subject} / ${x.target} / ${x.time} / ${x.time_text||''}；强度 ${x.intensity??'不适用'}；支持度 ${x.support??'未知'}`,'muted')}}for(const x of v.answer.observations||[]){const e=add(d,'div','','obs');add(e,'b',x.meaning);add(e,'p','「'+x.quote+'」 '+x.reason);add(e,'p',`${x.subject} / ${x.target} / ${x.time}；强度 ${x.intensity??'不适用'}；支持度 ${x.support??'未知'}`,'muted')}}}}
fetch('review-data.json').then(r=>r.json()).then(d=>{rows=d.rows;const s=d.summary;$('#cost').textContent=`B输出token增加 ${(s.B_over_A_completion_token_increase*100).toFixed(1)}%；单次请求中位耗时从 ${s.cost.A.median_request_seconds.toFixed(1)} 秒增至 ${s.cost.B.median_request_seconds.toFixed(1)} 秒。两版在同一并发队列运行，不能把耗时简单累加成GPU计费。`;const t=add($('#issues'),'table',''),tr=add(t,'tr','');for(const x of ['复核标出的问题帖子数','A','B'])add(tr,'th',x);for(const [k,l]of Object.entries(fields).filter(([k])=>!['minor','uncertain'].includes(k))){const rr=add(t,'tr','');add(rr,'td',l);add(rr,'td',s.issue_post_counts.A[k]);add(rr,'td',s.issue_post_counts.B[k])}add($('#issues'),'p','同一帖可有多种问题，行数不能相加；这些是助手复核的发现，不是全量语料错误率。','muted');render()}).catch(e=>{$('#rows').textContent='加载失败：'+e});$('#q').oninput=$('#filter').onchange=()=>{page=0;render()};$('#prev').onclick=()=>{page=Math.max(0,page-1);render()};$('#next').onclick=()=>{page++;render()};
</script></main></html>'''
(D/'report.html').write_text(page)
# Preserve original review data, only make the completion and destination visible.
f=P/'exports/summary.json';s=load(f);s.update({'quality_status':'completed_assistant_review','quality_report':'../quality-review/report.html','quality_verdict_counts':dict(counts)});f.write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n')
f=P/'exports/review.html';text=f.read_text().replace('<h1>原计划：80条新帖，两版配对复核</h1>','<h1>原计划：80条新帖，两版配对复核</h1><div class="card"><b>质量比较已完成：B 14条更好、A 10条更好、53条无明确优劣、3条各有得失。</b><p>排除12条边界敏感判断后，双方各6胜。B输出量增加22.2%，暂不替换默认版本。</p><a href="../quality-review/report.html">查看质量结论和全部80条复核理由</a></div>').replace('尚未作出语义优劣判定。','质量比较已完成，见上方报告。');f.write_text(text)
print(json.dumps(summary,ensure_ascii=False))
